// Group menus and icons follow the service order, then region/multiplier, then utility groups.
function configureGroupPresentation(config, nodeGroups) {
  const qure = name => 'https://fastly.jsdelivr.net/gh/Koolson/Qure@master/IconSet/Color/' + name + '.png';
  const lige = name => 'https://fastly.jsdelivr.net/gh/lige47/QuanX-icon-rule@main/icon/' + name + '.png';
  const icons = personalGroupIcons();
  const regionIcons = Object.assign(Object.create(null), {
    '香港': qure('Hong_Kong'),
    '日本': qure('Japan'),
    '美国': qure('United_States'),
    '新加坡': qure('Singapore'),
    '台湾': qure('Taiwan'),
    '德国': qure('Germany'),
    '英国': qure('United_Kingdom'),
    '荷兰': lige('01Country/Netherlands'),
  });
  const order = [
    '代理连接', 'AI', 'TELEGRAM', 'Discord', 'Twitter',
    'DLsite', 'EHentai', 'Media', 'GOOGLE', 'PikPak', 'FCM',
  ];
  const trailingVisible = ['直接连接', '代理DNS'];
  const hiddenLast = ['最低延迟', '故障转移', 'GLOBAL'];
  const groups = config['proxy-groups'];
  const byName = new Map(groups.map(group => [group.name, group]));
  const buckets = nodeGroups.buckets || [];
  const bucketNames = new Set(buckets.flatMap(bucket => [bucket.parent, ...bucket.children]));

  // Keep additional services before the node menus without guessing from names.
  for (const group of groups) {
    if (!order.includes(group.name) && !bucketNames.has(group.name) && !trailingVisible.includes(group.name) && !hiddenLast.includes(group.name)) {
      order.push(group.name);
    }
    if (icons[group.name]) group.icon = icons[group.name];
    else if (!group.icon) group.icon = qure('Stack');
  }
  for (const kind of ['region', 'other', 'multiplier']) {
    for (const bucket of buckets.filter(item => item.kind === kind)) {
      order.push(bucket.parent, ...bucket.children);
      const parent = byName.get(bucket.parent);
      if (parent) parent.icon = bucket.kind === 'region'
        ? regionIcons[bucket.label] || qure('World_Map')
        : bucket.kind === 'other' ? qure('World_Map')
          : qure(bucket.label === '低倍率节点' ? 'Available_1' : 'Airport');
      for (const name of bucket.children) {
        const child = byName.get(name);
        if (child) {
          child.hidden = true;
          child.icon = qure('Auto');
        }
      }
    }
  }
  order.push(...trailingVisible, ...hiddenLast);
  for (const name of hiddenLast) if (byName.has(name)) byName.get(name).hidden = true;
  const rank = new Map(order.map((name, index) => [name, index]));
  const compare = (left, right) => (rank.get(left) ?? order.length) - (rank.get(right) ?? order.length);
  groups.sort((left, right) => compare(left.name, right.name));
  const global = byName.get('GLOBAL');
  if (Array.isArray(global?.proxies)) {
    // Reordering the menu must not silently change its initial selected route.
    if (global['default-selected'] === undefined && global.proxies.length) global['default-selected'] = global.proxies[0];
    global.proxies.sort(compare);
  }
  return config;
}


// Keep DNS classification consistent with the personal traffic rules.
// Run before importing subscription DNS, whose explicit ECS must be preserved.
function publicDnsResolvers(addresses, group, ecsMode) {
  const upstreamEcs = {
    'https://dns.google/dns-query': '8.8.8.8/24',
    'https://dns.quad9.net/dns-query': '9.9.9.9/24',
  };
  return addresses.map(address => {
    let routed = personalDnsThroughGroup(address, group);
    const subnet = upstreamEcs[address.split('#')[0]];
    if (ecsMode === 'upstream' && subnet && !/[#&]ecs=/.test(routed)) routed += '&ecs=' + subnet + '&ecs-override=true';
    return routed;
  });
}

// General resolvers keep their explicitly configured route. Application and
// node-specific DNS policies have already been built and remain independent.
function configureGeneralDns(config, addresses) {
  const extra = addresses.map(address => {
    const selector = (address.split('#')[1] || '').split('&').find(part => part && !part.includes('='));
    return personalDnsThroughGroup(address, !selector || selector === 'DIRECT' ? '直接连接' : selector);
  });
  config.dns.nameserver = [...new Set([...config.dns.nameserver, ...extra])];
  for (const [key, resolvers] of Object.entries(config.dns['nameserver-policy'])) {
    if (Array.isArray(resolvers) && resolvers.length && resolvers.every(address =>
      typeof address === 'string' && address.split('#')[1]?.split('&')[0] === '代理DNS')) {
      config.dns['nameserver-policy'][key] = [...new Set([...resolvers, ...extra])];
    }
  }
}

function withoutForcedEcs(address) {
  if (typeof address !== 'string' || !address.includes('#')) return address;
  const split = address.indexOf('#');
  const parameters = address.slice(split + 1).split('&').filter(part => {
    const key = part.split('=')[0].toLowerCase();
    return key !== 'ecs' && key !== 'ecs-override';
  });
  return address.slice(0, split) + (parameters.length ? '#' + parameters.join('&') : '');
}

function patchDnsExperience(config, lists, options) {
  const settings = options || {};
  const mode = settings.ecsMode || 'resolver-default';
  if (!['resolver-default', 'upstream'].includes(mode)) throw new Error('未知 ECS 模式：' + mode);
  const dns = config.dns;
  const mapResolvers = value => Array.isArray(value) ? value.map(withoutForcedEcs) : withoutForcedEcs(value);
  if (mode === 'resolver-default') {
    for (const key of ['nameserver', 'direct-nameserver']) if (dns[key]) dns[key] = mapResolvers(dns[key]);
    for (const [key, value] of Object.entries(dns['nameserver-policy'] || {})) dns['nameserver-policy'][key] = mapResolvers(value);
  }
  if (settings.directRules === false) return config;
  const payload = entries => [...new Set(entries.map(rule => {
    const [type, domain] = rule.split(',');
    if (type === 'DOMAIN') return domain;
    if (type === 'DOMAIN-SUFFIX') return '+.' + domain;
    throw new Error('DNS 域名清单包含不支持的规则类型：' + type);
  }))];
  const providers = config['rule-providers'];
  if (providers['personal-direct']) throw new Error('个人 DNS 规则集与基础配置重名');
  providers['personal-direct'] = { type: 'inline', behavior: 'domain', payload: payload([...lists.downloads, ...lists.onedrive, ...lists['microsoft-direct'], ...lists['extra-direct'], ...lists['academic-direct']]) };
  const filterIndex = dns['fake-ip-filter'].indexOf('RULE-SET,ads,fake-ip');
  if (dns['fake-ip-filter-mode'] !== 'rule' || filterIndex < 0) throw new Error('基础配置的 Fake-IP 规则不支持个人 DNS 分类');
  dns['fake-ip-filter'].splice(filterIndex + 1, 0, 'RULE-SET,personal-direct,real-ip');
  const policies = {};
  let inserted = false;
  for (const [key, value] of Object.entries(dns['nameserver-policy'])) {
    policies[key] = value;
    if (key !== 'rule-set:ads') continue;
    policies['rule-set:personal-direct'] = [...dns['direct-nameserver']];
    inserted = true;
  }
  if (!inserted) throw new Error('基础配置缺少广告 DNS 规则，无法确定个人 DNS 顺序');
  dns['nameserver-policy'] = policies;
  return config;
}


